export interface AccountActionInput {
  action: "send_password_reset" | "sign_out_everywhere" | "mark_under_review" | "clear_review" | "restrict_messaging" | "restrict_ordering" | "restrict_reviews" | "restrict_account" | "suspend" | "reinstate" | "close";
  reasonCode: "customer_request" | "suspected_takeover" | "abusive_messages" | "payment_fraud_review" | "policy_violation" | "other";
  /** Required: what happened and what evidence was checked */
  details: string;
  /** For restrictions; null = until lifted */
  endsAt?: string | null;
  /** Shown to the customer with the restriction; defaults from the reason */
  customerMessage?: string | null;
  trustReportId?: string | null;
}

export const AccountActionInput: z.ZodType<AccountActionInput> = z.object({
  action: z.enum(["send_password_reset", "sign_out_everywhere", "mark_under_review", "clear_review", "restrict_messaging", "restrict_ordering", "restrict_reviews", "restrict_account", "suspend", "reinstate", "close"]),
  reasonCode: z.enum(["customer_request", "suspected_takeover", "abusive_messages", "payment_fraud_review", "policy_violation", "other"]),
  details: z.string().describe("Required: what happened and what evidence was checked"),
  endsAt: z.iso.datetime({ offset: true }).describe("For restrictions; null = until lifted").nullish(),
  customerMessage: z.string().describe("Shown to the customer with the restriction; defaults from the reason").nullish(),
  trustReportId: z.uuid().nullish(),
}).register(common.apiTypes, { id: "customers.AccountActionInput" });

export interface AccountActionResult {
  accountStatus: "active" | "under_review" | "restricted" | "suspended" | "closed";
  record: AccountActionRecord;
  restriction?: AccountRestriction | null;
  /** What changed and what stays available, e.g. 'Existing orders, returns, refunds and cases stay open' */
  effects: string[];
}

export const AccountActionResult: z.ZodType<AccountActionResult> = z.object({
  accountStatus: z.enum(["active", "under_review", "restricted", "suspended", "closed"]),
  get record() {
    return AccountActionRecord;
  },
  get restriction() {
    return AccountRestriction.nullish();
  },
  effects: z.array(z.string()).describe("What changed and what stays available, e.g. 'Existing orders, returns, refunds and cases stay open'"),
}).register(common.apiTypes, { id: "customers.AccountActionResult" });

